{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260927T230048Z/cell-362a9D/src/address.js","content":"/** Column/row helpers for cell addresses (A1, B12, AA3, ...). */

const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/** Convert 1- or 2-letter column text to its 1-based column index. */
export function colFromLetters(letters) {
  const upper = letters.toUpperCase()
  if (upper.length === 1) {
    return upper.charCodeAt(0) - 65 + 1
  }
  const first = upper.charCodeAt(0) - 65
  const second = upper.charCodeAt(1) - 65
  return 27 + first * 26 + second
}

/** Convert a 1-based column index back to its letter form. */
export function colToLetters(index) {
  if (index <= 26) {
    return String.fromCharCode(64 + index)
  }
  const rem = index - 27
  const first = Math.floor(rem / 26)
  const second = rem % 26
  return String.fromCharCode(65 + first) + String.fromCharCode(65 + second)
}

/**
 * Parse a raw word as a cell address. Returns null when the text is not
 * shaped like an address at all (letters/digits mismatch), or an object
 * `{ col, row, address, inRange }` otherwise. `inRange` is false when the
 * shape is right but the value falls outside the addressable range (more
 * than two letters, more than three digits, or row zero) -- callers treat
 * that as the address-outside-range case rather than a shape failure.
 */
export function parseAddress(word) {
  const m = ADDRESS_RE.exec(word)
  if (!m) return { inRange: false }
  const row = parseInt(m[2], 10)
  if (row < 1) return { inRange: false }
  const col = colFromLetters(m[1])
  const address = m[1].toUpperCase() + String(row)
  return { inRange: true, col, row, address }
}

/** Compare two canonical addresses by column then row. */
export function compareAddresses(a, b) {
  if (a.col !== b.col) return a.col - b.col
  return a.row - b.row
}
"}

