/**
 * Split a formula body into tokens. Throws nothing; an unrecognized
 * character produces an INVALID token that the parser will reject on.
 */
export function tokenize(text) {
  const tokens = []
  let i = 0
  const n = text.length
  while (i < n) {
    const ch = text[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (ch >= '0' && ch <= '9') {
      let j = i + 1
      while (j < n && text[j] >= '0' && text[j] <= '9') j++
      if (j < n && text[j] === '.') {
        let k = j + 1
        while (k < n && text[k] >= '0' && text[k] <= '9') k++
        if (k > j + 1) {
          tokens.push({ type: 'NUM', value: text.slice(i, k) })
          i = k
          continue
        }
      }
      tokens.push({ type: 'NUM', value: text.slice(i, j) })
      i = j
      continue
    }
    if (/[A-Za-z]/.test(ch)) {
      let j = i + 1
      while (j < n && /[A-Za-z0-9]/.test(text[j])) j++
      tokens.push({ type: 'WORD', value: text.slice(i, j) })
      i = j
      continue
    }
    if (ch === '(') { tokens.push({ type: 'LPAREN' }); i++; continue }
    if (ch === ')') { tokens.push({ type: 'RPAREN' }); i++; continue }
    if (ch === ':') { tokens.push({ type: 'COLON' }); i++; continue }
    if (ch === ',') { tokens.push({ type: 'COMMA' }); i++; continue }
    if (ch === '^') { tokens.push({ type: 'OP', value: '^' }); i++; continue }
    if (ch === '*') { tokens.push({ type: 'OP', value: '*' }); i++; continue }
    if (ch === '/') { tokens.push({ type: 'OP', value: '/' }); i++; continue }
    if (ch === '+') { tokens.push({ type: 'OP', value: '+' }); i++; continue }
    if (ch === '-') { tokens.push({ type: 'OP', value: '-' }); i++; continue }
    if (ch === '=') { tokens.push({ type: 'OP', value: '=' }); i++; continue }
    if (ch === '<') {
      if (text[i + 1] === '=') { tokens.push({ type: 'OP', value: '<=' }); i += 2; continue }
      if (text[i + 1] === '>') { tokens.push({ type: 'OP', value: '<>' }); i += 2; continue }
      tokens.push({ type: 'OP', value: '<' }); i++; continue
    }
    if (ch === '>') {
      if (text[i + 1] === '=') { tokens.push({ type: 'OP', value: '>=' }); i += 2; continue }
      tokens.push({ type: 'OP', value: '>' }); i++; continue
    }
    tokens.push({ type: 'INVALID', value: ch })
    i++
  }
  tokens.push({ type: 'EOF' })
  return tokens
}
"}

