{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260927T230048Z/cell-362a9D/src/parser.js","content":"/** Recursive-descent parser for formula bodies. */

import { tokenize } from './tokenizer.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const FUNCTION_NAMES = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

class ParseFailure extends Error {}

class Cursor {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.tokens[this.pos]
  }

  next() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const t = this.next()
    if (t.type !== type) throw new ParseFailure()
    return t
  }
}

/**
 * Parse a formula body (the text after `=`). Returns the AST root, or
 * null when the text does not fit the grammar.
 */
export function parseFormula(text) {
  const tokens = tokenize(text)
  const cursor = new Cursor(tokens)
  try {
    const node = parseComparison(cursor)
    if (cursor.peek().type !== 'EOF') throw new ParseFailure()
    return node
  } catch (e) {
    if (e instanceof ParseFailure) return null
    throw e
  }
}

function parseComparison(cursor) {
  let left = parseAdditive(cursor)
  while (cursor.peek().type === 'OP' && COMPARISON_OPS.has(cursor.peek().value)) {
    const op = cursor.next().value
    const right = parseAdditive(cursor)
    left = { kind: 'binary', op, left, right }
  }
  return left
}

function parseAdditive(cursor) {
  let left = parseMultiplicative(cursor)
  while (cursor.peek().type === 'OP' && (cursor.peek().value === '+' || cursor.peek().value === '-')) {
    const op = cursor.next().value
    const right = parseMultiplicative(cursor)
    left = { kind: 'binary', op, left, right }
  }
  return left
}

function parseMultiplicative(cursor) {
  let left = parsePower(cursor)
  while (cursor.peek().type === 'OP' && (cursor.peek().value === '*' || cursor.peek().value === '/')) {
    const op = cursor.next().value
    const right = parsePower(cursor)
    left = { kind: 'binary', op, left, right }
  }
  return left
}

function parsePower(cursor) {
  const left = parseUnary(cursor)
  if (cursor.peek().type === 'OP' && cursor.peek().value === '^') {
    cursor.next()
    const right = parsePower(cursor)
    return { kind: 'binary', op: '^', left, right }
  }
  return left
}

function parseUnary(cursor) {
  const t = cursor.peek()
  if (t.type === 'OP' && (t.value === '-' || t.value === '+')) {
    cursor.next()
    const arg = parsePrimary(cursor)
    return { kind: 'unary', op: t.value, arg }
  }
  return parsePrimary(cursor)
}

function parsePrimary(cursor) {
  const t = cursor.peek()
  if (t.type === 'NUM') {
    cursor.next()
    return { kind: 'num', value: parseFloat(t.value) }
  }
  if (t.type === 'LPAREN') {
    cursor.next()
    const inner = parseComparison(cursor)
    cursor.expect('RPAREN')
    return inner
  }
  if (t.type === 'WORD') {
    cursor.next()
    const upper = t.value.toUpperCase()
    if (upper === 'TRUE') return { kind: 'bool', value: true }
    if (upper === 'FALSE') return { kind: 'bool', value: false }
    if (cursor.peek().type === 'LPAREN') {
      return parseCallArgs(cursor, upper)
    }
    if (cursor.peek().type === 'COLON') {
      cursor.next()
      const toTok = cursor.next()
      if (toTok.type !== 'WORD') throw new ParseFailure()
      const toUpper = toTok.value.toUpperCase()
      if (toUpper === 'TRUE' || toUpper === 'FALSE') throw new ParseFailure()
      if (cursor.peek().type === 'LPAREN') throw new ParseFailure()
      return { kind: 'range', from: t.value, to: toTok.value }
    }
    return { kind: 'cell', word: t.value }
  }
  throw new ParseFailure()
}

function parseCallArgs(cursor, name) {
  cursor.expect('LPAREN')
  const args = []
  if (cursor.peek().type !== 'RPAREN') {
    args.push(parseArgument(cursor))
    while (cursor.peek().type === 'COMMA') {
      cursor.next()
      args.push(parseArgument(cursor))
    }
  }
  cursor.expect('RPAREN')
  return { kind: 'call', name, args }
