export const ERROR_TOKENS = new Set([
  '#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!',
])

export function num(value) { return { type: 'number', value } }
export function text(value) { return { type: 'text', value } }
export function bool(value) { return { type: 'boolean', value } }
export function err(token) { return { type: 'error', value: token } }

export const ERR_DIV0 = err('#DIV/0!')
export const ERR_REF = err('#REF!')
export const ERR_VALUE = err('#VALUE!')
export const ERR_CYCLE = err('#CYCLE!')
export const ERR_NAME = err('#NAME?')
export const ERR_ERR = err('#ERR!')

/** Convert a value to a number for arithmetic, or an error value. */
export function toNumberOrError(v) {
  if (v.type === 'error') return v
  if (v.type === 'number') return v
  if (v.type === 'boolean') return num(v.value ? 1 : 0)
  return ERR_VALUE
}

/** Convert a value to a boolean for a condition, or an error value. */
export function toBoolOrError(v) {
  if (v.type === 'error') return v
  if (v.type === 'boolean') return v.value
  if (v.type === 'number') return v.value !== 0
  return ERR_VALUE
}

/** Rank used to order values of different kinds in a comparison. */
function kindRank(v) {
  if (v.type === 'number') return 0
  if (v.type === 'text') return 1
  return 2
}

/** Compare two non-error values per the cross-kind ordering rules. */
export function compareValues(a, b) {
  const ra = kindRank(a)
  const rb = kindRank(b)
  if (ra !== rb) return ra - rb
  if (a.type === 'number') return a.value - b.value
  if (a.type === 'text') return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
  return (a.value ? 1 : 0) - (b.value ? 1 : 0)
}

/** Round to ten significant digits, the way JavaScript would print it. */
export function formatNumber(n) {
  const rounded = Number(n.toPrecision(10))
  return String(rounded)
}

/** Format a value for `values` output. */
export function formatValue(v) {
  if (v.type === 'number') return formatNumber(v.value)
  if (v.type === 'boolean') return v.value ? 'TRUE' : 'FALSE'
  if (v.type === 'error') return v.value
  return v.value
}
