import { parseAddress, colToLetters, compareAddresses } from './address.js'
import { parseFormula } from './parser.js'
import {
  num, text, err, ERR_ERR, ERR_REF, ERR_VALUE, ERR_CYCLE, ERR_NAME, ERR_DIV0,
  toNumberOrError, toBoolOrError, compareValues, ERROR_TOKENS,
} from './values.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const AGGREGATORS = new Set(['SUM', 'MIN', 'MAX', 'AVG'])

const NUMBER_LITERAL_RE = /^-?[0-9]+(\.[0-9]+)?$/

function classifyLiteral(content) {
  if (content === '') return num(0)
  if (ERROR_TOKENS.has(content)) return err(content)
  if (NUMBER_LITERAL_RE.test(content)) return num(parseFloat(content))
  return text(content)
}

/** Expand a range's corners into an ordered list of covered addresses. */
function rangeCells(fromWord, toWord) {
  const from = parseAddress(fromWord)
  const to = parseAddress(toWord)
  if (!from.inRange || !to.inRange) return null
  const colMin = Math.min(from.col, to.col)
  const colMax = Math.max(from.col, to.col)
  const rowMin = Math.min(from.row, to.row)
  const rowMax = Math.max(from.row, to.row)
  const list = []
  for (let c = colMin; c <= colMax; c++) {
    for (let r = rowMin; r <= rowMax; r++) {
      list.push(colToLetters(c) + String(r))
    }
  }
  return list
