    if (cache.has(address)) return cache.get(address)
    const decl = cells.get(address)
    if (!decl) {
      const v = num(0)
      cache.set(address, v)
      return v
    }
    if (visiting.has(address)) return ERR_CYCLE
    visiting.add(address)
    const v = evalContent(decl.content)
    visiting.delete(address)
    cache.set(address, v)
    return v
  }

  function evalContent(content) {
    if (content.startsWith('=')) {
      const ast = parseFormula(content.slice(1))
      if (!ast) return ERR_ERR
      return evalNode(ast)
    }
    return classifyLiteral(content)
  }

