  function flattenArg(node) {
    if (node.kind === 'range') {
      const list = rangeCells(node.from, node.to)
      if (!list) return [ERR_REF]
      return list.map(getValue)
    }
    return [evalNode(node)]
  }

  function firstErrorConverted(flat) {
    for (const v of flat) {
      const c = toNumberOrError(v)
      if (c.type === 'error') return c
    }
    return null
  }

  function firstErrorRaw(flat) {
    for (const v of flat) {
      if (v.type === 'error') return v
    }
    return null
  }

  function evalNode(node) {
    switch (node.kind) {
      case 'num': return num(node.value)
      case 'bool': return { type: 'boolean', value: node.value }
      case 'range': return ERR_ERR
      case 'cell': {
        const parsed = parseAddress(node.word)
        if (!parsed.inRange) return ERR_REF
        return getValue(parsed.address)
      }
      case 'unary': {
        const argVal = evalNode(node.arg)
        const c = toNumberOrError(argVal)
        if (c.type === 'error') return c
        return num(node.op === '-' ? -c.value : c.value)
      }
      case 'binary': return evalBinary(node)
      case 'call': return evalCall(node)
