      if (leftVal.type === 'error') return leftVal
      if (rightVal.type === 'error') return rightVal
      const cmp = compareValues(leftVal, rightVal)
      let result
      switch (node.op) {
        case '=': result = cmp === 0; break
        case '<>': result = cmp !== 0; break
        case '<': result = cmp < 0; break
        case '<=': result = cmp <= 0; break
        case '>': result = cmp > 0; break
        case '>=': result = cmp >= 0; break
      }
      return { type: 'boolean', value: result }
    }
    const lc = toNumberOrError(leftVal)
    if (lc.type === 'error') return lc
    const rc = toNumberOrError(rightVal)
    if (rc.type === 'error') return rc
    let result
    switch (node.op) {
      case '+': result = lc.value + rc.value; break
