      const firstErr = firstErrorConverted(flat)
      if (firstErr) return firstErr
      const v = flat.length > 0 ? toNumberOrError(flat[0]).value : 0
      const result = Math.abs(v)
      if (!Number.isFinite(result)) return ERR_DIV0
      return num(result)
    }

    if (name === 'COUNT') {
      if (node.args.length < 1) return ERR_ERR
      const flat = node.args.flatMap(flattenArg)
      const firstErr = firstErrorRaw(flat)
      if (firstErr) return firstErr
      return num(flat.filter((v) => v.type === 'number').length)
    }

