    if (node.args.length < 1) return ERR_ERR
    const flat = node.args.flatMap(flattenArg)
    const firstErr = firstErrorConverted(flat)
    if (firstErr) return firstErr
    const nums = flat.map((v) => toNumberOrError(v).value)
    let result
    if (name === 'SUM') result = nums.reduce((a, b) => a + b, 0)
    else if (name === 'MIN') result = Math.min(...nums)
    else if (name === 'MAX') result = Math.max(...nums)
    else result = nums.reduce((a, b) => a + b, 0) / nums.length
    if (!Number.isFinite(result)) return ERR_DIV0
    return num(result)
  }

  function evalIf(args) {
    if (args.length !== 3) return ERR_ERR
    const condFlat = flattenArg(args[0])
    const condErr = firstErrorRaw(condFlat)
    if (condErr) return condErr
    const condVal = condFlat.length > 0 ? condFlat[0] : ERR_VALUE
    const condResult = toBoolOrError(condVal)
    if (typeof condResult !== 'boolean') return condResult
    const branch = condResult ? args[1] : args[2]
    const branchFlat = flattenArg(branch)
    return branchFlat.length > 0 ? branchFlat[0] : ERR_VALUE
  }

  return { getValue }
}

/** Evaluate every declared cell; returns entries sorted by address. */
export function evaluateSheet(cells) {
  const evaluator = createEvaluator(cells)
  const addresses = sortedAddresses(cells)
  return addresses.map((address) => [address, evaluator.getValue(address)])
}

function sortedAddresses(cells) {
  const entries = [...cells.keys()].map((address) => ({ address, ...parseAddress(address) }))
  entries.sort(compareAddresses)
  return entries.map((e) => e.address)
}

/** Collect the cells a formula names directly, ranges expanded. */
function collectRefs(node, seen) {
  switch (node.kind) {
    case 'cell': {
      const parsed = parseAddress(node.word)
      if (parsed.inRange) seen.set(parsed.address, parsed)
      break
    }
    case 'range': {
      const list = rangeCells(node.from, node.to)
      if (list) {
        for (const address of list) seen.set(address, parseAddress(address))
      }
      break
    }
    case 'unary':
      collectRefs(node.arg, seen)
      break
    case 'binary':
      collectRefs(node.left, seen)
      collectRefs(node.right, seen)
      break
    case 'call':
      for (const arg of node.args) collectRefs(arg, seen)
      break
    default:
      break
  }
}

/** Dependencies for every declared cell, sorted by address. */
export function collectDeps(cells) {
  const addresses = sortedAddresses(cells)
  return addresses.map((address) => {
    const decl = cells.get(address)
    const seen = new Map()
    if (decl.content.startsWith('=')) {
      const ast = parseFormula(decl.content.slice(1))
      if (ast) collectRefs(ast, seen)
    }
    const deps = [...seen.values()].sort(compareAddresses).map((e) => e.address)
    return [address, deps]
  })
}
